css:
:root {
  --primary: #c2703d;
  --primary-hover: #a95526;
  --bg: #f5e9dc;
  --bg-alt: #f0decb;
  --card-bg: #fffdf8;
  --text: #453931;
  --text-secondary: #6b5e54;
  --border: #d2c0aa;
  --shadow-soft: 0 8px 24px rgba(54, 31, 16, 0.12);
  --shadow-strong: 0 14px 40px rgba(54, 31, 16, 0.2);
  --accent-pencil: #f6c145;
  --accent-ink: #2e4057;
}

body {
  background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.4), transparent 35%),
              radial-gradient(circle at 80% 10%, rgba(255, 255, 255, 0.3), transparent 30%),
              linear-gradient(135deg, #f8efdf 0%, #f1dcc1 38%, #ead1b0 100%);
  color: var(--text);
}

.header {
  background: repeating-linear-gradient(90deg, #fdf7ed 0 18px, #f1e2d1 18px 36px);
  border-bottom: 3px solid var(--accent-pencil);
  box-shadow: var(--shadow-soft);
}

.brand {
  font-family: "DM Serif Text", "Times New Roman", serif;
  color: var(--accent-ink);
  letter-spacing: 0.04em;
  text-shadow: 1px 1px 0 #f6c145, 2px 2px 0 #ffffff;
}

.toolbar button,
.toolbar .btn,
.toolbar .input,
.toolbar select {
  border-radius: 20px;
  background: linear-gradient(180deg, #fffdf7 0%, #f3e4d1 100%);
  border: 1px solid #d7c6b1;
  color: var(--text);
  box-shadow: inset 0 1px 0 #ffffff, var(--shadow-soft);
  transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.toolbar button:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-strong);
}

.card {
  background: var(--card-bg);
  border: 1px solid #e7d8c5;
  border-radius: 12px;
  box-shadow: var(--shadow-soft);
  position: relative;
  padding: 16px 18px;
  transition: transform 0.18s ease, box-shadow 0.18s ease, rotate 0.18s ease;
  transform: rotate(calc(-2deg + 4deg * (var(--card-index, 0) % 2)));
}

.card::before {
  content: "";
  position: absolute;
  inset: 8px 12px 6px 12px;
  border-radius: 10px;
  background: repeating-linear-gradient(#fefbf6, #fefbf6 8px, #f5efe6 9px, #f5efe6 10px);
  mix-blend-mode: multiply;
  opacity: 0.78;
  pointer-events: none;
}

.card::after {
  content: "";
  position: absolute;
  width: 64px;
  height: 18px;
  top: -10px;
  left: 18px;
  background: linear-gradient(135deg, #ffe6a7 0%, #f6c145 100%);
  border-radius: 4px;
  box-shadow: 0 6px 8px rgba(0,0,0,0.12);
  transform: rotate(-3deg);
}

.card:hover {
  transform: translateY(-6px) rotate(-1deg);
  box-shadow: var(--shadow-strong);
}

.card .card-title {
  font-family: "Work Sans", "Inter", sans-serif;
  font-weight: 700;
  color: var(--accent-ink);
}

.card .card-body {
  line-height: 1.7;
  color: var(--text-secondary);
}

.card .tag,
.card .label {
  background: #f6c145;
  color: #2f241c;
  border: none;
  border-radius: 6px;
  padding: 6px 10px;
  box-shadow: inset 0 -1px 0 rgba(0,0,0,0.1), 0 2px 6px rgba(0,0,0,0.1);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sidebar,
.panel,
.modal,
.popover {
  background: #fffaf2;
  border: 1px solid #e6d5be;
  box-shadow: var(--shadow-strong);
}

.list-item,
.menu-item,
.dropdown-item {
  background: #fffaf3;
  border-radius: 10px;
  padding: 10px 12px;
  transition: background 0.15s ease;
}

.list-item:hover,
.menu-item:hover,
.dropdown-item:hover {
  background: #f6e6d1;
}

.floating-ribbon {
  background: linear-gradient(90deg, #f6c145 0%, #e69f5c 100%);
  color: #2e1f18;
  box-shadow: var(--shadow-soft);
  border-radius: 12px;
}

.timeline::before,
.board::before {
  background: repeating-linear-gradient(0deg, rgba(0,0,0,0.04) 0 2px, transparent 2px 16px);
}
